variants.html:
{% comment %} json_script escapes the payload and puts it in a script tag the browser will
   not execute. Never interpolate JSON into an attribute: one apostrophe in a
   supplier name ends the attribute and takes the page with it.

   money is loaded here rather than assumed. rupees is the only filter in this
   block that is not a builtin, and a template that omits the load tag raises
   TemplateSyntaxError on the row loop rather than on the line that needs it,
   which sends the next person looking in the wrong place. It is rupees and not
   intcomma because Indian grouping is 2,2,3 above the last three digits:
   intcomma returns 1,245,000 where the figure reads 12,45,000, and a number
   wrong by a factor of ten is read straight past. table/django defines it. {% endcomment %}
{% load money %}
{{ spend_by_month|json_script:"spend-by-month" }}

<div data-kui="chart/django" class="rounded-xl border border-zinc-300 bg-white p-5"
     x-data="{
       chart: null, gone: false,
       init() { this.wait(() => this.draw()); },
       /* Tailwind's browser build compiles after first paint, so a class can
          still be uncompiled when Alpine initialises and getComputedStyle
          hands back transparent. Check every swatch, not the first: they do
          not all land in the same pass. With a compiled stylesheet this
          passes on the first frame and costs nothing. The gone flag is the
          teardown case: a card swapped out by htmx while the loop is still
          running would otherwise resolve a frame later and build a Chart on
          a detached canvas that nothing is left alive to destroy. */
       wait(fn) {
         if (this.gone) return;
         const probes = Array.from(this.$refs.legend.querySelectorAll('[data-series]'));
         probes.every(el => getComputedStyle(el).backgroundColor !== 'rgba(0, 0, 0, 0)')
           ? fn()
           : requestAnimationFrame(() => this.wait(fn));
       },
       draw() {
         Chart.defaults.font.family = getComputedStyle(this.$root).fontFamily;
         const rows = JSON.parse(document.getElementById('spend-by-month').textContent);
         const grid = getComputedStyle(this.$root).borderTopColor;
         const ink  = getComputedStyle(this.$refs.legend).color;
         const tone = Array.from(this.$refs.legend.querySelectorAll('[data-series]'))
                           .map(el => getComputedStyle(el).backgroundColor);
         this.chart = new Chart(this.$refs.canvas, {
           type: 'line',
           data: {
             labels: rows.map(r => r.month),
             datasets: [{
               label: 'Committed value', data: rows.map(r => r.value),
               borderColor: tone[0], backgroundColor: tone[0],
               borderWidth: 2, pointRadius: 0, pointHoverRadius: 4, tension: 0.3
             }]
           },
           options: {
             responsive: true, maintainAspectRatio: false,
             interaction: { mode: 'index', intersect: false },
             scales: {
               x: { grid: { display: false }, border: { color: grid }, ticks: { color: ink } },
               y: { beginAtZero: true, grid: { color: grid }, border: { display: false },
                    ticks: { color: ink, padding: 8, callback: v => (v / 100000).toFixed(1).replace('.0', '') + 'L' } }
             },
             plugins: { tooltip: { callbacks: { label: c => '₹' + c.parsed.y.toLocaleString('en-IN') } } }
           }
         });
       },
       destroy() { this.gone = true; this.chart && this.chart.destroy(); }
     }">

  <div class="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
    <h3 class="text-[14px]/5 font-semibold">Committed value by month</h3>
    <p class="text-[12px]/4 tabular-nums text-zinc-500">{{ plant.name }} · {{ year }}</p>
  </div>

  <ul x-ref="legend" class="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-[12px]/4 text-zinc-600">
    <li class="flex items-center gap-1.5">
      <span data-series class="size-2 rounded-full bg-zinc-800" aria-hidden="true"></span>Committed value
    </li>
  </ul>

  <div class="mt-4 h-64">
    <canvas x-ref="canvas" role="img" aria-label="{{ chart_summary }}"></canvas>
  </div>

  <div class="sr-only">
    <table>
      <caption>Committed value by month, {{ plant.name }}, {{ year }}</caption>
      <thead><tr><th scope="col">Month</th><th scope="col">Committed value</th></tr></thead>
      <tbody>
        {% for row in spend_by_month %}
          <tr><th scope="row">{{ row.month }}</th><td>{{ row.value|rupees }}</td></tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
</div>

{% if inspection.photos.exists %}
<div data-kui="carousel/django" x-data="{
       i: 0, n: 0, atStart: true, atEnd: true,
       slides() { return Array.from(this.$refs.rail.children).filter(el => el.localName !== 'template'); },
       pad() { return parseFloat(getComputedStyle(this.$refs.rail).scrollPaddingLeft) || 0; },
       sync() {
         const r = this.$refs.rail, s = this.slides(), edge = r.getBoundingClientRect().left + this.pad();
         this.n = s.length;
         this.atStart = r.scrollLeft < 2;
         this.atEnd = r.scrollLeft > r.scrollWidth - r.clientWidth - 2;
         const near = s.map((el, k) => [Math.abs(el.getBoundingClientRect().left - edge), k]).sort((a, b) => a[0] - b[0]);
         this.i = near.length ? near[0][1] : 0;
       },
       go(k) {
         const r = this.$refs.rail, s = this.slides(), el = s[Math.min(Math.max(k, 0), s.length - 1)];
         if (!el) return;
         r.scrollBy({ left: el.getBoundingClientRect().left - r.getBoundingClientRect().left - this.pad(),
                      behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
       }
     }"
     x-init="sync()"
     @resize.window.debounce="sync()">

  <div class="mb-3 flex items-center justify-between gap-3">
    <h3 class="text-[14px]/5 font-semibold">Photographs</h3>
    <div class="flex items-center gap-2">
      <p class="text-[12px]/4 tabular-nums text-zinc-500"><span x-text="i + 1"></span> of <span x-text="n"></span></p>
      <div class="hidden items-center gap-1 md:flex">
        <button type="button" @click="go(i - 1)" :disabled="atStart" aria-label="Previous photograph"
                class="flex h-8 w-8 items-center justify-center rounded-lg border border-zinc-300 bg-white text-zinc-600 hover:bg-zinc-200 hover:text-zinc-900 focus-visible:outline-3 focus-visible:outline-offset-2 focus-visible:outline-zinc-700/15 disabled:pointer-events-none disabled:opacity-40">
          <i data-lucide="chevron-left" class="size-4"></i>
        </button>
        <button type="button" @click="go(i + 1)" :disabled="atEnd" aria-label="Next photograph"
                class="flex h-8 w-8 items-center justify-center rounded-lg border border-zinc-300 bg-white text-zinc-600 hover:bg-zinc-200 hover:text-zinc-900 focus-visible:outline-3 focus-visible:outline-offset-2 focus-visible:outline-zinc-700/15 disabled:pointer-events-none disabled:opacity-40">
          <i data-lucide="chevron-right" class="size-4"></i>
        </button>
      </div>
    </div>
  </div>

  {# the loop is server side, so there is no x-for template for slides() to filter out #}
  <div x-ref="rail" @scroll.passive="sync()" tabindex="0" role="group" aria-label="Photographs on inspection {{ inspection.reference }}"
       @keydown.arrow-right="if ($event.target === $refs.rail) { $event.preventDefault(); go(i + 1); }"
       @keydown.arrow-left="if ($event.target === $refs.rail) { $event.preventDefault(); go(i - 1); }"
       class="flex snap-x snap-mandatory gap-3 overflow-x-auto rounded-xl focus-visible:outline-3 focus-visible:outline-offset-2 focus-visible:outline-zinc-700/15 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
    {% for photo in inspection.photos.all %}
      <figure class="shrink-0 basis-full snap-start overflow-hidden rounded-xl border border-zinc-300 bg-white">
        <img src="{{ photo.image.url }}" alt="{{ photo.caption }}" loading="lazy" decoding="async"
             class="aspect-video w-full bg-zinc-100 object-cover">
        <figcaption class="border-t border-zinc-200 px-4 py-2.5">
          <p class="truncate text-[13px]/5 font-medium">{{ photo.caption }}</p>
          <p class="mt-0.5 truncate text-[12px]/4 text-zinc-500 tabular-nums">
            {{ photo.filename }} · {{ photo.taken_at|date:"d M Y H:i" }} IST
          </p>
        </figcaption>
      </figure>
    {% endfor %}
  </div>
</div>
{% else %}
<div class="rounded-xl border border-dashed border-zinc-300 bg-white px-6 py-10 text-center">
  <span class="mx-auto flex size-10 items-center justify-center rounded-full bg-zinc-200 ring-1 ring-inset ring-zinc-300">
    <i data-lucide="image" class="size-4 text-zinc-600"></i>
  </span>
  <p class="mt-3 text-[14px]/5 font-medium">No photographs on this inspection</p>
  <p class="mx-auto mt-1 max-w-sm text-[13px]/5 text-zinc-600">Photos taken at the gate appear here in the order they were uploaded.</p>
</div>
{% endif %}
